//! Your own list of models to download: `catalog.json` in the models folder.
//!
//! Ember's built-in list only holds models whose terms let the project point at them. Anything else (a stronger
//! recogniser whose weights are for research use, a model you trained, a mirror you trust) can be added by you: each entry
//! is a model manifest (the same fields as a `face-model.json`) plus the address to fetch it from, and it then gets the same
//! Download button as a built-in one, with its licence notice shown before anything is fetched. Ember ships and links to
//! none of them; what the file says, and whether you may use the weights, is yours to check.
//!
//! ```json
//! { "models": [ {
//!     "id": "my-recogniser", "name": "My recogniser", "version": "1", "role": "embedder",
//!     "url": "https://example.org/weights/recogniser.onnx",
//!     "sha256": "…64 lowercase hex digits…", "sizeBytes": 166000000,
//!     "licence": { "name": "Research use only", "commercial": "no", "notice": "Not for commercial use." },
//!     "provenance": "Trained on …",
//!     "output": { "kind": "embedding", "dim": 512 },
//!     "thresholds": { "matchCosine": 0.4 },
//!     "speed": 1.7
//! } ] }
//! ```
//!
//! `speed` (optional) is how many times faster the model is than a ResNet-100, shown in Settings instead of timings.
//! `input` may be left out (112 × 112 RGB, `(x − 127.5) / 127.5`, the ArcFace convention). The file is untrusted: it is read
//! with a size limit, every entry is validated, and a bad entry is reported and skipped, never a reason to refuse the rest.
//! The `sha256` and `sizeBytes` are required, since they are what a downloaded file is checked against.

use serde::Deserialize;
use serde_json::Value;

use crate::known::{self, Download};
use crate::manifest::{self, ModelManifest, Role};

/// Largest `catalog.json` we read.
pub const MAX_CATALOG_BYTES: usize = 256 * 1024;
/// Most entries we take from it.
pub const MAX_ENTRIES: usize = 50;

/// One model from the catalog: its manifest, where to fetch it and what to call the file meanwhile.
#[derive(Clone, Debug, PartialEq)]
pub struct Entry {
    pub manifest: ModelManifest,
    pub url: String,
    pub file_name: String,
}

impl Entry {
    /// What the download machinery needs. (`sha256` and `size_bytes` are present: [`parse`] requires them.)
    pub fn download(&self) -> Option<Download> {
        Some(Download {
            id: self.manifest.id.clone(),
            url: self.url.clone(),
            file_name: self.file_name.clone(),
            size_bytes: self.manifest.size_bytes?,
            sha256: self.manifest.sha256.clone()?,
        })
    }
}

/// What a catalog file holds.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Catalog {
    pub entries: Vec<Entry>,
    /// One plain sentence for each entry (or the file) that could not be used.
    pub errors: Vec<String>,
}

#[derive(Deserialize)]
struct Raw {
    url: String,
    #[serde(flatten)]
    manifest: ModelManifest,
}

/// A file name for the download, from the address: letters, digits, `.`, `_`, `-`, ending in `.onnx`.
fn file_name_of(url: &str) -> String {
    let last = url.split(['?', '#']).next().unwrap_or("").rsplit('/').next().unwrap_or("");
    let clean: String = last.chars().filter(|c| c.is_ascii_alphanumeric() || matches!(c, '.' | '_' | '-')).take(80).collect();
    if clean.ends_with(".onnx") && clean.len() > 5 && !clean.starts_with('.') { clean } else { "model.onnx".to_string() }
}

fn entry(v: &Value) -> Result<Entry, String> {
    let raw: Raw = serde_json::from_value(v.clone()).map_err(|e| e.to_string())?;
    manifest::validate(&raw.manifest).map_err(|e| e.to_string())?;
    let m = &raw.manifest;
    if m.role != Role::Embedder {
        return Err("only face recognition models (role \"embedder\") can be downloaded".into());
    }
    if m.sha256.is_none() || m.size_bytes.is_none() {
        return Err("needs `sha256` and `sizeBytes`: a download is checked against them".into());
    }
    if !(raw.url.len() <= 500 && raw.url.starts_with("https://") && !raw.url.chars().any(|c| c.is_control() || c.is_whitespace())) {
        return Err("`url` must be an https:// address of at most 500 characters, without spaces".into());
    }
    if known::all().iter().any(|k| k.id == m.id) {
        return Err("that id belongs to a model Ember already knows".into());
    }
    if m.sha256.as_deref().is_some_and(|h| known::lookup(h).is_some()) {
        return Err("Ember already knows a model with that file".into());
    }
    Ok(Entry { file_name: file_name_of(&raw.url), url: raw.url, manifest: raw.manifest })
}

/// Read a catalog file's bytes: the usable entries, and why the others were left out.
pub fn parse(bytes: &[u8]) -> Catalog {
    let mut out = Catalog::default();
    if bytes.len() > MAX_CATALOG_BYTES {
        out.errors.push(format!("catalog.json is larger than {} KB: not read", MAX_CATALOG_BYTES / 1024));
        return out;
    }
    // Notepad and older PowerShell begin a UTF-8 file with a byte-order mark
    let bytes = bytes.strip_prefix(&[0xEF, 0xBB, 0xBF]).unwrap_or(bytes);
    let value: Value = match serde_json::from_slice(bytes) {
        Ok(v) => v,
    { ... }
            .and_then(Value::as_str)
            .map_or_else(|| format!("model {}", i + 1), |id| format!("`{}`", id.chars().take(40).collect::<String>()));
        match entry(v) {
            Ok(e) if out.entries.iter().any(|x| x.manifest.id == e.manifest.id) => {
                out.errors.push(format!("{label}: listed twice, the first is used"))
            }
            Ok(e) => out.entries.push(e),
            Err(why) => out.errors.push(format!("{label}: {why}")),
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn good(id: &str) -> Value {
        json!({
            "id": id, "name": "Test model", "version": "1", "role": "embedder",
            "url": "https://example.org/w/recogniser-r50.onnx?download=1",
            "sha256": "ab".repeat(32), "sizeBytes": 1234,
            "licence": {"name": "Research only", "commercial": "no", "notice": "Not for commercial use."},
            "output": {"kind": "embedding", "dim": 512}, "thresholds": {"matchCosine": 0.4}, "speed": 1.7,
        })
    }

    fn cat(models: Vec<Value>) -> Catalog {
        parse(json!({"models": models}).to_string().as_bytes())
    }

    #[test]
    fn a_manifest_with_an_address_is_a_downloadable_model() {
        let c = cat(vec![good("my-model")]);
        assert_eq!(c.errors, Vec::<String>::new());
        let e = &c.entries[0];
        assert_eq!((e.manifest.id.as_str(), e.file_name.as_str()), ("my-model", "recogniser-r50.onnx"), "the file name comes from the address");
        assert_eq!(e.manifest.licence.commercial, crate::Commercial::No, "a non-commercial model is the user's to add");
        let d = e.download().unwrap();
        assert_eq!((d.size_bytes, d.sha256.len(), d.url.as_str()), (1234, 64, "https://example.org/w/recogniser-r50.onnx?download=1"));
        assert_eq!(e.manifest.input, crate::InputSpec::default(), "the input defaults to the ArcFace convention");
        assert_eq!(e.manifest.speed, Some(1.7), "the speed ratio is the user's to state");
        let mut nonsense = good("nonsense-speed");
        nonsense["speed"] = json!(-3);
        let c = cat(vec![nonsense]);
        assert!(c.entries.is_empty() && c.errors.iter().any(|e| e.contains("speed")), "{:?}", c.errors);
    }

    #[test]
    fn a_file_saved_with_a_byte_order_mark_still_reads() {
        let mut bytes = vec![0xEF, 0xBB, 0xBF];
        bytes.extend_from_slice(json!({"models": [good("with-bom")]}).to_string().as_bytes());
        let c = parse(&bytes);
        assert_eq!((c.entries.len(), c.errors.len()), (1, 0), "{:?}", c.errors);
    }

    #[test]
    fn bad_entries_are_reported_and_the_rest_still_load() {
        let mut no_hash = good("no-hash");
        no_hash.as_object_mut().unwrap().remove("sha256");
        let mut http = good("plain-http");
        http["url"] = json!("http://example.org/m.onnx");
        let mut spaces = good("spaces");
        spaces["url"] = json!("https://example.org/a b.onnx");
        let mut detector = good("a-detector");
        detector["role"] = json!("detector");
        detector["output"] = json!({"kind": "detector", "decoder": "yunet-v2"});
        let mut bad_id = good("Bad/Id");
        bad_id["id"] = json!("../escape");
        let builtin = good("sface-2021dec");
        let mut known_file = good("known-file");
        known_file["sha256"] = json!(known::SFACE_SHA256);
        let c = cat(vec![good("fine"), no_hash, http, spaces, detector, bad_id, builtin, known_file, good("fine"), json!(7), json!({"id": "x"})]);
        assert_eq!(c.entries.iter().map(|e| e.manifest.id.as_str()).collect::<Vec<_>>(), ["fine"]);
        assert_eq!(c.errors.len(), 10, "{:#?}", c.errors);
        assert!(c.errors.iter().any(|e| e.contains("`no-hash`") && e.contains("sha256")));
        assert!(c.errors.iter().any(|e| e.contains("https")));
        assert!(c.errors.iter().any(|e| e.contains("already knows")));
        assert!(c.errors.iter().any(|e| e.contains("listed twice")));
    }

    #[test]
    fn a_hostile_or_broken_file_is_an_error_message_not_a_crash() {
        for bytes in [&b""[..], b"not json", b"[]", b"{}", b"{\"models\": 5}", b"\xff\xfe\x00", &vec![b' '; MAX_CATALOG_BYTES + 1]] {
            let c = parse(bytes);
            assert!(c.entries.is_empty() && !c.errors.is_empty(), "{:?}", String::from_utf8_lossy(&bytes[..bytes.len().min(20)]));
        }
        // more entries than allowed: the extra are ignored, with a note
        let many: Vec<Value> = (0..MAX_ENTRIES + 20).map(|i| good(&format!("m{i}"))).collect();
        let c = cat(many);
        assert_eq!(c.entries.len(), MAX_ENTRIES);
        assert!(c.errors.iter().any(|e| e.contains("first")));
        // file names from odd addresses are safe
        for url in ["https://x.org/a/b/c.onnx", "https://x.org/", "https://x.org/..%2f..%2fevil.onnx", "https://x.org/q.bin", "https://x.org/.onnx"] {
            let got = file_name_of(url);
            assert!(!got.contains(['/', '\\']) && got.ends_with(".onnx") && !got.starts_with('.'), "{url} -> {got}");
        }
    }
}

//! The models LightCraft recognises by their SHA-256, with what is honestly known about each.
//!
//! The licence and provenance texts here are what the user reads before enabling a model, so they say what
//! is *not* known too. Weights are never part of LightCraft: every model is an opt-in the user installs.

use crate::manifest::{Colour, Commercial, InputSpec, Licence, ModelManifest, OutputSpec, Resize, Role, Thresholds};

/// Detector output decoders built into LightCraft.
pub const DECODERS: &[&str] = &["yunet-v2"];

/// The id of the face detector LightCraft runs (see [`yunet`]).
pub const YUNET_ID: &str = "yunet-2023mar";
pub const YUNET_SHA256: &str = "8f2383e4dd3cfbb4553ea8718107fc0423210dc964f9f4280604804ed2552fa4";
pub const SFACE_SHA256: &str = "0ba9fbfa01b5270c96627c4ef784da859931e02f04419c829e83484087c34e79";
pub const AURAFACE_SHA256: &str = "a7933ea5330113b01c9b60351d8f4c33003f145d8470ac5f0e52ee2effe25c60";

fn licence(name: &str, commercial: Commercial, url: &str, notice: &str) -> Licence {
    Licence { name: name.into(), commercial, url: Some(url.into()), notice: notice.into() }
}

/// YuNet 2023mar (OpenCV Zoo): a small face detector.
pub fn yunet() -> ModelManifest {
    ModelManifest {
        id: YUNET_ID.into(),
        name: "YuNet (face detector)".into(),
        version: "2023mar".into(),
        role: Role::Detector,
        licence: licence(
            "MIT",
            Commercial::Yes,
            "https://github.com/opencv/opencv_zoo/blob/main/models/face_detection_yunet/LICENSE",
            "MIT licence, copyright Shiqi Yu. A separate opt-in download.",
        ),
        source: Some("https://github.com/opencv/opencv_zoo/tree/main/models/face_detection_yunet".into()),
        sha256: Some(YUNET_SHA256.into()),
        size_bytes: Some(232_589),
        provenance:
            "Trained on WIDER FACE, whose terms are not settled by the weights' MIT licence. A detector: it finds faces, it does not identify anyone."
                .into(),
        input: InputSpec { width: 640, height: 640, colour: Colour::Bgr, mean: [0.0; 3], std: [1.0; 3], resize: Resize::Letterbox },
        output: OutputSpec::Detector { decoder: "yunet-v2".into() },
        thresholds: Thresholds { match_cosine: None, score: Some(0.6), nms_iou: Some(0.3) },
        speed: None,
    }
}

/// SFace 2021dec (OpenCV Zoo). Its match threshold is a starting point: on 755 named faces (busts, matched across
/// shots more than five seconds apart) 0.55 gave 97.5% right suggestions for 88% of faces; `faces.evaluate` checks it on
/// your own photos.
pub fn sface() -> ModelManifest {
    ModelManifest {
        id: "sface-2021dec".into(),
        name: "SFace (face recogniser)".into(),
        version: "2021dec".into(),
        role: Role::Embedder,
        licence: licence(
            "Apache-2.0 (as labelled by OpenCV Zoo)",
            Commercial::Unknown,
            "https://github.com/opencv/opencv_zoo/tree/main/models/face_recognition_sface",
            "Labelled Apache-2.0, but what it was trained on is not documented, and two questions about commercial use (opencv_zoo issues 313 and 318) are unanswered. Fine to try for yourself; do not redistribute.",
        ),
        source: Some("https://github.com/opencv/opencv_zoo/tree/main/models/face_recognition_sface".into()),
        sha256: Some(SFACE_SHA256.into()),
        size_bytes: Some(38_696_353),
        provenance: "Undocumented. The original SFace repository mentions CASIA-WebFace, VGGFace2 and MS1MV2.".into(),
        input: InputSpec { width: 112, height: 112, colour: Colour::Rgb, mean: [0.0; 3], std: [1.0; 3], resize: Resize::Stretch },
        output: OutputSpec::Embedding { dim: 128 },
        thresholds: Thresholds { match_cosine: Some(0.55), ..Thresholds::default() },
        speed: Some(6.9),
    }
}

/// AuraFace v1 `glintr100` (fal.ai). Starting-point threshold: on the same 755 faces 0.40 gave 96.6% right suggestions
/// for 56% of faces (0.30: 97.3% for 85%).
pub fn auraface() -> ModelManifest {
    ModelManifest {
        id: "auraface-v1".into(),
        name: "AuraFace v1 (face recogniser)".into(),
        version: "1".into(),
        role: Role::Embedder,
        licence: licence(
            "Apache-2.0",
            Commercial::Yes,
            "https://huggingface.co/fal/AuraFace-v1",
            "Apache-2.0. Its training data is described only as a commercial dataset, with no dataset named and no consent statement, and it covers some ethnicities less well. About 261 MB, and slow on a CPU.",
        ),
        source: Some("https://huggingface.co/fal/AuraFace-v1".into()),
        sha256: Some(AURAFACE_SHA256.into()),
        size_bytes: Some(260_694_151),
        provenance: "Undisclosed: \"a commercial dataset comprising face images from various sources\".".into(),
        input: InputSpec::default(),
        output: OutputSpec::Embedding { dim: 512 },
        thresholds: Thresholds { match_cosine: Some(0.40), ..Thresholds::default() },
        speed: Some(1.0),
    }
}

/// Every model we know by hash.
pub fn all() -> Vec<ModelManifest> {
    vec![yunet(), sface(), auraface()]
}

/// The known model whose file has this SHA-256 (lowercase hex).
pub fn lookup(sha256: &str) -> Option<ModelManifest> {
    all().into_iter().find(|m| m.sha256.as_deref() == Some(sha256))
}

/// Where the user's "Download" button fetches a model from. The URL is pinned to a commit of the model's own
/// repository, and what arrives is checked against the manifest's size and SHA-256 before anything uses it.
#[derive(Clone, Debug, PartialEq)]
pub struct Download {
    pub id: String,
    pub url: String,
    /// The name the file is kept under while it waits for the user to accept its terms.
    pub file_name: String,
    pub size_bytes: u64,
    pub sha256: String,
}

/// Pinned download addresses by model id. Only models whose terms allow us to point at them are here: a model
/// that is marked non-commercial is never offered for download (the user brings the file themselves).
const SOURCES: &[(&str, &str, &str)] = &[
    (
        YUNET_ID,
        "https://github.com/opencv/opencv_zoo/raw/25f423d0e04c31a17254620e58febd7386da523b/models/face_detection_yunet/face_detection_yunet_2023mar.onnx",
        "face_detection_yunet_2023mar.onnx",
    ),
    (
        "sface-2021dec",
        "https://github.com/opencv/opencv_zoo/raw/25f423d0e04c31a17254620e58febd7386da523b/models/face_recognition_sface/face_recognition_sface_2021dec.onnx",
        "face_recognition_sface_2021dec.onnx",
    ),
    ("auraface-v1", "https://huggingface.co/fal/AuraFace-v1/resolve/af6d057c9b0ec4071d4c49c80e3539258798b609/glintr100.onnx", "glintr100.onnx"),
];

/// How to download the model with this id, if LightCraft offers to.
pub fn download(id: &str) -> Option<Download> {
    let (_, url, file_name) = SOURCES.iter().find(|(i, _, _)| *i == id)?;
    let m = all().into_iter().find(|m| m.id == id)?;
    if m.licence.commercial == Commercial::No {
        return None;
    }
    Some(Download { id: m.id, url: (*url).into(), file_name: (*file_name).into(), size_bytes: m.size_bytes?, sha256: m.sha256? })
}

/// "github.com" for a download address: what the user is told the file comes from.
pub fn host(url: &str) -> &str {
    url.strip_prefix("https://").and_then(|r| r.split('/').next()).unwrap_or("")
}

impl Download {
    /// The address without the file name (the downloader's "mirror": it fetches `<mirror>/<file name>`).
    pub fn base(&self) -> &str {
        self.url.strip_suffix(self.file_name.as_str()).map_or(self.url.as_str(), |b| b.trim_end_matches('/'))
    }

    /// The site the file comes from, as the user is told.
    pub fn host(&self) -> &str {
        host(&self.url)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::manifest::validate;

    #[test]
    fn known_models_are_valid_and_unique() {
    { ... }
        ids.sort();
        ids.dedup();
        assert_eq!(ids.len(), all.len(), "unique ids");
        let mut hashes: Vec<_> = all.iter().filter_map(|m| m.sha256.as_deref()).collect();
        hashes.sort();
        hashes.dedup();
        assert_eq!(hashes.len(), all.len(), "unique hashes");
    }

    #[test]
    fn lookup_finds_by_hash() {
        assert_eq!(lookup(AURAFACE_SHA256).map(|m| m.id), Some("auraface-v1".to_string()));
        assert_eq!(lookup(YUNET_SHA256).map(|m| m.role), Some(Role::Detector));
        assert!(lookup(&"0".repeat(64)).is_none());
        assert!(lookup("").is_none());
    }

    #[test]
    fn downloads_are_pinned_checked_and_only_for_models_we_may_point_at() {
        for m in all() {
            let Some(d) = download(&m.id) else { continue };
            assert!(d.url.starts_with("https://"), "{}: https only", d.id);
            assert!(!d.url.contains("/main/") && !d.url.contains("/master/"), "{}: pinned to a commit, not a branch", d.id);
            assert!(d.file_name.ends_with(".onnx") && !d.file_name.contains(['/', '\\']), "{}", d.file_name);
            assert!(d.url.ends_with(&format!("/{}", d.file_name)), "{}: the address ends in the file's name", d.id);
            assert!(d.base().starts_with("https://") && !d.base().ends_with('/') && !d.base().ends_with(".onnx"), "{}", d.base());
            assert_eq!((Some(d.size_bytes), Some(d.sha256.as_str())), (m.size_bytes, m.sha256.as_deref()), "{}", d.id);
            assert!(m.licence.commercial != Commercial::No, "{} is non-commercial and must not be offered", d.id);
        }
        assert_eq!(download("yunet-2023mar").map(|d| d.host().to_string()).as_deref(), Some("github.com"));
        assert_eq!(download("sface-2021dec").map(|d| host(&d.url).to_string()).as_deref(), Some("github.com"));
        assert_eq!(download("auraface-v1").map(|d| host(&d.url).to_string()).as_deref(), Some("huggingface.co"));
        // unknown ids and path tricks have nothing to download
        for id in ["nope", "", "../sface-2021dec", "SFACE-2021DEC"] {
            assert!(download(id).is_none(), "{id}");
        }
        // every address in the table belongs to a known model
        for (id, _, _) in SOURCES {
            assert!(all().iter().any(|m| m.id == *id), "{id}");
        }
    }

    #[test]
    fn unresolved_models_say_so() {
        assert_eq!(sface().licence.commercial, Commercial::Unknown);
        assert!(sface().provenance.to_lowercase().contains("undocumented"));
        assert!(auraface().provenance.to_lowercase().contains("undisclosed"));
    { ... }

//! A face model's manifest: what the model is, what it needs and who may use it, as plain data.
//!
//! A manifest comes from the known-model table, from a suggestion made for a file the user dropped in, or
//! from a `face-model.json` next to a model. All of those are untrusted: [`validate`] must pass before a
//! manifest is used, and [`parse`] applies it after reading JSON of bounded size.

use serde::{Deserialize, Serialize};

/// Largest `face-model.json` we read.
pub const MAX_MANIFEST_BYTES: usize = 64 * 1024;
/// Largest model file we accept (bytes).
pub const MAX_MODEL_BYTES: u64 = 512 * 1024 * 1024;

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Role {
    /// Finds faces (boxes, and landmarks when the model has them).
    Detector,
    /// Turns an aligned face into a vector whose distance says whether two faces are the same person.
    Embedder,
}

/// Whether the weights may be used commercially.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Commercial {
    Yes,
    /// Research or personal use only. Never bundled or redistributed by LightCraft.
    No,
    /// The licence or the training data is unclear: the user is told so before installing.
    Unknown,
}

#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase")]
pub struct Licence {
    /// SPDX id or a short name ("MIT", "Apache-2.0", "InsightFace non-commercial research").
    pub name: String,
    pub commercial: Commercial,
    pub url: Option<String>,
    /// Plain-language terms shown before the model is enabled.
    pub notice: String,
}

impl Default for Licence {
    fn default() -> Self {
        Self { name: String::new(), commercial: Commercial::Unknown, url: None, notice: String::new() }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Colour {
    Rgb,
    Bgr,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub enum Resize {
    /// Stretch the crop to the input size (aligned face crops).
    Stretch,
    /// Keep the aspect ratio and pad (whole photos for a detector).
    Letterbox,
}

/// How an image becomes the model's input: NCHW float, `(pixel − mean) / std` per channel, pixel in 0..255.
#[derive(Clone, Copy, Debug, PartialEq, Serialize, Deserialize)]
#[serde(default, rename_all = "camelCase")]
pub struct InputSpec {
    pub width: u32,
    pub height: u32,
    pub colour: Colour,
