    #[test]
    fn post_sends_exact_bounded_body_once() {
        use std::io::{BufRead, BufReader};
        let server = std::net::TcpListener::bind("127.0.0.1:0").unwrap();
        let addr = server.local_addr().unwrap();
        let worker = std::thread::spawn(move || {
            let (mut socket, _) = server.accept().unwrap();
            socket.set_read_timeout(Some(Duration::from_secs(3))).unwrap();
            let mut reader = BufReader::new(&socket);
            let mut head = String::new();
            loop {
                let mut line = String::new();
                reader.read_line(&mut line).unwrap();
                head.push_str(&line);
                if line == "\r\n" {
                    break;
                }
            }
            assert!(head.starts_with("POST /test HTTP/1.1\r\n"));
            assert!(head.contains("Content-Length: 2\r\n"));
            assert!(head.contains("Content-Type: application/json\r\n"));
            let mut body = [0; 2];
            reader.read_exact(&mut body).unwrap();
            assert_eq!(&body, b"{}");
            drop(reader);
            socket.write_all(b"HTTP/1.1 200 OK\r\nContent-Length: 2\r\nConnection: close\r\n\r\n{}").unwrap();
        });
        let cancel = AtomicBool::new(false);
        let limits = Limits {
            connect: Duration::from_secs(2),
            stall: Duration::from_secs(2),
            cancel: &cancel,
            deadline: Instant::now().checked_add(Duration::from_secs(3)),
        };
        let mut response = post_json(&Url::parse(&format!("http://{addr}/test")).unwrap(), &[], b"{}", &limits).unwrap();
        assert_eq!(response.status, 200);
        let mut bytes = [0; 2];
        assert_eq!(response.read(&mut bytes, &limits).unwrap(), 2);
        assert_eq!(&bytes, b"{}");
        worker.join().unwrap();
    }

    #[test]
    fn post_rejects_missing_deadline_oversize_and_cancel_before_connect() {
        let cancel = AtomicBool::new(true);
        let url = Url::parse("http://127.0.0.1:1/test").unwrap();
        let mut limits = Limits { connect: Duration::from_secs(1), stall: Duration::from_secs(1), cancel: &cancel, deadline: None };
        assert!(matches!(post_json(&url, &[], b"{}", &limits), Err(HttpError::Protocol(_))));
        limits.deadline = Instant::now().checked_add(Duration::from_secs(1));
        assert!(matches!(post_json(&url, &[], b"{}", &limits), Err(HttpError::Cancelled)));
        assert!(matches!(post_json(&url, &[], &vec![0; 4 * 1024 * 1024 + 1], &limits), Err(HttpError::Protocol(_))));
        assert!(matches!(post_json(&url, &[("Authorization", "key\r\nInjected: 1".into())], b"{}", &limits), Err(HttpError::BadUrl(_))));
        cancel.store(false, Ordering::Relaxed);
        limits.deadline = Some(Instant::now());
        assert!(matches!(post_json(&url, &[], b"{}", &limits), Err(HttpError::Stalled)));
    }
}

//! The downloader against a local HTTP server (std `TcpListener`; never the internet): mirror
//! fallback, redirects, resuming, chunked bodies, stalls, hash mismatches, size caps, cancel.

use std::io::{BufRead, BufReader, Write};
use std::net::{TcpListener, TcpStream};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::time::{Duration, Instant};

use super::*;

/// The served file: 300 kB of a deterministic pattern.
fn payload() -> Vec<u8> {
    (0..300_000u32).map(|i| (i.wrapping_mul(2_654_435_761) >> 13) as u8).collect()
}

fn sha_hex(b: &[u8]) -> String {
    Sha256::digest(b).iter().map(|b| format!("{b:02x}")).collect()
}

fn leak(s: String) -> &'static str {
    Box::leak(s.into_boxed_str())
}

fn pinned() -> FileSpec<'static> {
    let p = payload();
    FileSpec { name: "model.bin", size: Some(p.len() as u64), sha256: Some(leak(sha_hex(&p))), max: p.len() as u64 }
}

struct Server {
    base: String,
    hits: Arc<AtomicUsize>,
}

/// Serve on 127.0.0.1; the first path segment picks the behaviour.
fn server() -> Server {
    let l = TcpListener::bind("127.0.0.1:0").unwrap();
    let base = format!("http://{}", l.local_addr().unwrap());
    let hits = Arc::new(AtomicUsize::new(0));
    let h = hits.clone();
    std::thread::spawn(move || {
        for s in l.incoming().flatten() {
            let h = h.clone();
            std::thread::spawn(move || handle(s, &h));
        }
    });
    Server { base, hits }
}

fn handle(mut s: TcpStream, hits: &AtomicUsize) {
    let n = hits.fetch_add(1, Ordering::SeqCst);
    let mut r = BufReader::new(s.try_clone().unwrap());
    let mut first = String::new();
    if r.read_line(&mut first).is_err() {
        return;
    }
    let mut range: Option<u64> = None;
    loop {
        let mut l = String::new();
        if r.read_line(&mut l).unwrap_or(0) == 0 || l.trim().is_empty() {
            break;
        }
        if let Some(v) = l.to_ascii_lowercase().strip_prefix("range: bytes=") {
            range = v.trim().trim_end_matches('-').parse().ok();
    { ... }
            // the first try breaks off after a third
            let _ = s.write_all(format!("HTTP/1.1 200 OK\r\nContent-Length: {}\r\n\r\n", body.len()).as_bytes());
            let _ = s.write_all(&body[..body.len() / 3]);
        }
        "range416" if range.is_some() => send(&mut s, "416 Range Not Satisfiable", "Content-Length: 0\r\n", b""),
        "norange" | "range416" => send(&mut s, "200 OK", &format!("Content-Length: {}\r\n", body.len()), &body),
        _ => match range {
            Some(from) if from as usize >= body.len() => send(&mut s, "416 Range Not Satisfiable", "Content-Length: 0\r\n", b""),
            Some(from) => send(
                &mut s,
                "206 Partial Content",
                &format!("Content-Range: bytes {from}-{}/{}\r\nContent-Length: {}\r\n", body.len() - 1, body.len(), body.len() - from as usize),
                &body[from as usize..],
            ),
            None => send(&mut s, "200 OK", &format!("Content-Length: {}\r\n", body.len()), &body),
        },
    }
}

fn tmp(name: &str) -> PathBuf {
    let d = std::env::temp_dir().join(format!("lc-sam3-fetch-{name}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    d
}

fn quick() -> Options {
    Options { connect_timeout: Duration::from_secs(2), stall_timeout: Duration::from_millis(600), attempts: 2, token_env: None }
}

fn run(files: &[FileSpec<'_>], mirrors: &[String], dir: &Path, cancel: &AtomicBool) -> (Result<(), DownloadError>, Vec<Progress>) {
    let mut seen = Vec::new();
    let r = download(files, mirrors, dir, &quick(), cancel, &mut |p| seen.push(p.clone()));
    (r, seen)
}

