        format!("{}/error", srv.base),
        "http://127.0.0.1:1/unreachable".to_string(),
        format!("{}/redirect", srv.base),
    ];
    let (r, seen) = run(&[pinned()], &mirrors, &dir, &AtomicBool::new(false));
